/// Constants for the research pretest/posttest instrument (`DATA_MODEL.md`
/// §6b/§6c, `CLAUDE.md` §10). They mirror the contract of the app-safe
/// bank `assets/research/instrument_v1.json` (generated by
/// `tools/research/bin/build_instrument.js`) and the research rules in
/// `firestore.rules`, so the app rejects a malformed bank before it ever
/// tries a write the rules would deny.
///
/// Nothing here is, or is derived from, the answer key.
library;

/// The only bank `schemaVersion` this app understands.
const int kResearchSchemaVersion = 1;

/// The bank's `instrumentId`.
const String kResearchInstrumentId = 'vocably-pretest-posttest';

/// Items per band — every attempt answers exactly this many.
const int kResearchItemsPerBand = 20;

/// Substantive (meaning) options per item, not counting "tidak tahu".
const int kResearchOptionsPerItem = 4;

/// The separate "I don't know this word" choice. The research rules accept
/// it only with this exact ID and text, always at display position 5.
const String kResearchDontKnowOptionId = 'dont_know';
const String kResearchDontKnowOptionText = 'Saya tidak tahu kata ini';

/// App-safe bank asset per supported `instrumentVersion`. A version not
/// listed here is unsupported and fails to load.
const Map<String, String> kResearchInstrumentAssets = {
  'v1': 'assets/research/instrument_v1.json',
};
